# implementamos el grafo
grafo_ejercicio_1 = {
    "A": ["B","C"],
    "B": ["D","E"],
    "C": ["F"],
    "D": [],
    "E": [],
    "F": []
}

#importamos libreria necesaria para FIFO.
from collections import deque

"""Implementamos la función de recorrido por anchura:"""

def bfs(grafo,inicio):
  cola = deque([inicio]) #creamos una cola con una lista
  visitados = set() #creamos un conjunto de visitados
  while cola: #mientras la cola no esté vacía (mientras haya nodos los cuales visitar)
    nodo = cola.popleft() #extraemos el primer nodo de la cola
    if nodo not in visitados: #si el nodo no está en los visitados
      print("visitando a -> ", nodo)
      visitados.add(nodo) #lo agregamos al conjunto de visitados

      for vecino in grafo[nodo]: #iteramos sobre los vecinos del nodo, para luego
        cola.append(vecino) # agregarlos a la cola

"""Una vez definida la función con la lógica, la probamos"""

bfs(grafo_ejercicio_1,"A")

"""Ejercicio 2: Ahora BFS no debe recorrer necesariamente todo el grafo. La búsqueda debe finalizar en el momento en que se encuentre el nodo objetivo."""

# implementamos el grafo de prueba para el ejercicio 2
grafo_ejercicio_2 = {
    "A": ["B","C"],
    "B": ["D","E"],
    "C": ["F","G"],
    "D": [],
    "E": [],
    "F": [],
    "G": []
}

"""ahora implementamos la función de busqueda por bfs"""

def bfs_buscar(grafo, inicio, objetivo):
  cola = deque([inicio]) #creamos una cola con una lista que almacena los nodos y sus hijos
  visitados = set() #creamos un conjunto de visitados
  camino = []
  while cola: #mientras la cola no esté vacía (mientras haya nodos los cuales visitar)
    nodo = cola.popleft() #extraemos el primer nodo de la cola
    if nodo not in visitados: #si el nodo no está en los visitados, lo visitamos
      visitados.add(nodo)
      camino.append(nodo)
      if nodo == objetivo: #si el nodo es el objetivo, terminamos la busqueda
        break
      for vecino in grafo[nodo]: #iteramos sobre los vecinos del nodo, para luego
        cola.append(vecino) # agregarlos a la cola
  if objetivo in visitados:
    print("el camino de ", inicio, " hasta ", objetivo," es: ", camino)
    return True
  else:
    print("el camino de ", inicio, " hasta ", objetivo , " no existe")
    return False

"""Ahora probamos la logica con 3 casos de prueba."""

bfs_buscar(grafo_ejercicio_2,"A","E") #si existe un camino
bfs_buscar(grafo_ejercicio_2,"A","G") #si existe un camino (el mas largo por el tipo de recorrido)
bfs_buscar(grafo_ejercicio_2,"B","F") #no hay camino

"""En este ejercicio no basta con saber que G es alcanzable. El algoritmo debe retornar el camino utilizado para llegar hasta el objetivo.

![image.png](data:image/png;base64,)
"""

# implementamos el grafo del ejercicio
grafo_ejercicio_3 = {
    "A": ["B","C"],
    "B": ["D","E"],
    "C": ["F"],
    "D": ["G"],
    "E": ["G"],
    "F": ["G"],
    "G": []
}

"""ahora implementamos la función, donde tambien vamos a validar que el camino sea el minimo posible."""

def bfs_ruta(grafo, inicio, objetivo):
  if inicio == objetivo: # si el inicio es igual al objetivo lo retornamos
        return [inicio]

  visitados = set(inicio) # inicializamos los visitados como un cojunto, luego marcamos al nodo de inicio como vistado
  cola = deque([(inicio, [inicio])]) # en la cola ingresamos una tupla, compuesta por el nodo actual y el camino hasta llegar a ese nodo

  while cola: #mientras la cola no está vacía
      nodo_actual, camino_actual = cola.popleft() #desempaquetamos la tupla, donde el primer elemento contiene el nodo actual y el segundo el camino hasta ese nodo
      for vecino in grafo[nodo_actual]: #recorremos los vecinos del nodo actual
          if vecino not in visitados: # si no ha sido visitado el vecino de la iésima iteracion lo visitamos y actualizamos el camino
              nuevo_camino = camino_actual + [vecino]
              if vecino == objetivo: # si algun vecino es igual al objetivo, hemos llegado a nuestro objetivo :D
                  return nuevo_camino
              visitados.add(vecino)
              cola.append((vecino, nuevo_camino))

  return None  # no existe camino #si la cola se vacía y el vecino nunca fue igual al objetivo, no existe camino

bfs_ruta(grafo_ejercicio_3, "A", "G")

